export interface OrganizationSummary {
  readonly organization: Organization;
  readonly usage: OrganizationUsage;
  readonly memberCount: number;
  readonly projectCount: number;
  /** Set while the workspace is read-only, so the shell can show a banner. */
  readonly lockReason: WorkspaceLockReason | null;
}

/**
 * Read-only rule for a workspace whose subscription is not in good standing.
 *
 * Pure: callers pass the subscription row and the instant of the write.
 * A missing row and an `active` subscription are writable. `past_due` locks
 * immediately. A trial locks at its period end. A cancellation locks at
 * `cancelAt`, and a canceled row with no cancellation date is locked now.
 */
import { parseIso } from "@/lib/date";
import type { WorkspaceLockReason, Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

const LOCK_MESSAGE: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "This workspace is read-only while the subscription is past due.",
  canceled: "This workspace is read-only because the subscription is canceled.",
  trial_ended: "This workspace is read-only because the trial has ended.",
};

export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(LOCK_MESSAGE[reason]);
    this.name = "WorkspaceLockedError";
  }
}

/** True once `instant` is the same moment as `now` or earlier. */
function hasReached(instant: Subscription["currentPeriodEnd"], now: Date): boolean {
  return now.getTime() >= parseIso(instant).getTime();
}

export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return hasReached(subscription.cancelAt, now) ? "canceled" : null;
    default: {
      const unexpected: never = subscription.status;
      void unexpected;
      return null;
    }
  }
}

